const b=$json.body||$json;
const requestId=String(b.request_id||('wf129-'+Date.now()));
const dealId=b.deal_id||null,leadId=b.lead_id||null,propertyId=b.property_id||null,exitExecutionId=b.exit_execution_id||null;
const strategy=String(b.exit_strategy||b.disposition_strategy||'').toLowerCase().replace(/ /g,'_').replace(/-/g,'_');
const buyerId=b.buyer_id||b.assignee_id||null;
const commitmentStatus=String(b.buyer_commitment_status||b.commitment_status||'').toLowerCase();
const acceptanceStatus=String(b.buyer_acceptance_status||b.acceptance_status||'').toLowerCase();
const depositStatus=String(b.deposit_status||b.emd_status||'').toLowerCase();
const depositRequired=Boolean(b.deposit_required||b.emd_required);
const depositAmount=Number.isFinite(Number(b.deposit_amount||b.emd_amount))?Number(b.deposit_amount||b.emd_amount):null;
const expiration=b.commitment_expiration||b.acceptance_expiration||null;
const fallbackBuyerId=b.fallback_buyer_id||null;
const dnc=Boolean(b.dnc),missing=[];
if(!dealId)missing.push('deal_id');if(!leadId)missing.push('lead_id');if(!propertyId)missing.push('property_id');if(!exitExecutionId)missing.push('exit_execution_id');if(!strategy)missing.push('exit_strategy');
const blockers=[];
if(!['assignment','novation','double_close'].includes(strategy))blockers.push('unsupported_exit_strategy');
if(!buyerId)blockers.push('buyer_missing');
if(!['accepted','committed','confirmed','ready'].includes(commitmentStatus)&&!['accepted','confirmed','ready'].includes(acceptanceStatus))blockers.push('buyer_commitment_not_confirmed');
if(depositRequired&&!['received','verified','confirmed','funded','complete'].includes(depositStatus))blockers.push('deposit_or_emd_not_confirmed');
if(depositRequired&&depositAmount!==null&&depositAmount<=0)blockers.push('deposit_amount_invalid');
if(expiration&&new Date(expiration).getTime()<Date.now()&&!['accepted','committed','confirmed','ready'].includes(commitmentStatus))blockers.push('commitment_expired');
let status='blocked',nextState='human_review',route='human_review',reason='Buyer commitment requires review';
if(dnc){status='suppressed';nextState='buyer_commitment';route='none';reason='DNC suppresses communication only; buyer commitment state is retained';}
else if(missing.length){status='blocked';nextState='missing_commitment_inputs';reason='Required disposition commitment identity is missing';}
else if(blockers.length){status='blocked';nextState=blockers.includes('commitment_expired')?'buyer_commitment_expired':'buyer_commitment_pending';route=fallbackBuyerId?'fallback_buyer_review':'human_review';reason='Buyer acceptance, commitment, deposit, or expiration conditions are unresolved';}
else{status='committed';nextState='transaction_tracking';route='wf-041-assignment-novation-double-close-transaction-tracking';reason='Buyer commitment and required deposit conditions are confirmed';}
const id='buyer-commitment:'+dealId+':'+requestId+':v1';
const uniqueBlockers=[...new Set(blockers)];
return[{json:{workflow:'WF-129',workflow_version:'1.0',request_id:requestId,buyer_commitment_id:id,exit_execution_id:exitExecutionId,lead_id:leadId,property_id:propertyId,deal_id:dealId,exit_strategy:strategy,buyer_id:buyerId,fallback_buyer_id:fallbackBuyerId,commitment_status:commitmentStatus,acceptance_status:acceptanceStatus,deposit_required:depositRequired,deposit_status:depositStatus,deposit_amount:depositAmount,commitment_expiration:expiration,status,next_state:nextState,route,reason,blockers:uniqueBlockers,requirements:['buyer acceptance or commitment evidence','deposit/EMD confirmation when required','commitment expiration tracking','fallback buyer path when available'],guardrails:{no_invented_buyer_commitment:true,deposit_required_means_confirmed_deposit:true,expired_commitments_block_execution:true,fallback_buyer_requires_separate_confirmation:true,dnc_suppresses_communication_not_transaction_state:true},crm_activity:{activity_type:'buyer_commitment',subject:'WF-129 buyer commitment - '+status,lead_id:leadId,property_id:propertyId,deal_id:dealId,external_id:id,external_source:'wholesaling-os-disposition',metadata:{status,next_state,route,reason,exit_strategy,buyer_id:buyerId,fallback_buyer_id:fallbackBuyerId,commitment_status:commitmentStatus,acceptance_status:acceptanceStatus,deposit_required:depositRequired,deposit_status:depositStatus,deposit_amount:depositAmount,commitment_expiration:expiration,blockers:uniqueBlockers}}}}];
